examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(text = "Drag a person onto their new manager, or select them and press M.", modifier = Modifier.weight(1f), style = MonarchTextStyle.Caption)
        MonarchButton(
            text = {{exportLabel}},
            onClick = {},
            variant = MonarchButtonVariant.Secondary,
            size = MonarchButtonSize.Sm,
        )
    }
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .border(MonarchTheme.spacing.px, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg)
            .background(MonarchTheme.colors.bgSubtle, MonarchTheme.shapes.lg),
    ) {
        @OptIn(ExperimentalMonarchApi::class)
        MonarchOrgChart(
            nodes = people,
            expandIcon = {
                MonarchIcon(
                    imageVector = SampleIcons.ChevronRight,
                    contentDescription = null,
                    size = MonarchIconSize.Sm,
                )
            },
            modifier = Modifier.height(900.dp),
            focusId = selectedId,
            dottedLines = listOf(MonarchOrgChartDottedLine(from = {{dottedLines.0.from}}, to = {{dottedLines.0.to}})),
            layout = MonarchOrgChartLayout.List,
            onSelect = { person -> selectedId = person.id },
        )
    }
    MonarchText(text = "Selected: " + (people.firstOrNull { it.id == selectedId }?.name ?: "nobody"))
}

