examples.setup:
var people by remember {
    mutableStateOf(
        listOf(
            MonarchOrgChartNode(id = "ana", name = "Ana Silva", title = "Chief executive"),
            MonarchOrgChartNode(id = "jo", parentId = "ana", name = "Jo Park", title = "Head of engineering", childCount = 2),
            MonarchOrgChartNode(id = "sam", parentId = "ana", name = "Sam Lee", title = "Head of finance"),
        ),
    )
}

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchOrgChart(
    nodes = people,
    expandIcon = { Text("›") },
    modifier = Modifier.height(420.dp),
    layout = MonarchOrgChartLayout.List,
    onLoadChildren = { manager ->
        people = people + listOf(
            MonarchOrgChartNode(id = "ola", parentId = manager.id, name = "Ola Berg"),
            MonarchOrgChartNode(id = "kai", parentId = manager.id, name = "Kai Moss"),
        )
    },
    onMoveRequest = { person, target ->
        val manager = when (target) {
            is MonarchOrgChartMoveTarget.Manager -> target.id
            MonarchOrgChartMoveTarget.TopLevel -> null
            // Ask where, for example in a dialog.
            MonarchOrgChartMoveTarget.Unspecified -> return@MonarchOrgChart
        }
        people = people.map {
            if (it.id == person.id) MonarchOrgChartNode(id = it.id, parentId = manager, name = it.name, title = it.title) else it
        }
    },
)
